import sys

def main():
    n = int(sys.stdin.read().strip())
    knights = []
    for i in range(n):
        knights.append((i % 10, i // 10))
    for i in range(n, max(n, n**2 // 10)):
        x, y = i % 10, i // 10
        while (x, y) in knights:
            x += 10
        knights.append((x, y))
    for x, y in knights[:n]:
        print(x, y)

main()
